package com.example.starter.forestry.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 业务时钟配置：统一使用 UTC 日界，测试中可替换为可控时钟。
 */
@Configuration
public class ClockConfig {

    /**
     * 系统 UTC 时钟，所有自然日边界（90 日采伐期限、更新期限等）均以此为准。
     */
    @Bean
    public Clock forestryClock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.forestry.config;

import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * 采伐监管业务参数。
 *
 * @param blacklistDays      列入限批名单的时长（天），期限内新申请一律拒绝
 * @param harvestWindowDays  发证后采伐期限（自然日，UTC 日界）
 * @param acceptancePassRate 更新验收合格率下限（百分比），恰达该值合格
 */
@ConfigurationProperties(prefix = "forestry")
public record ForestryProperties(int blacklistDays, int harvestWindowDays, int acceptancePassRate) {
}

package com.example.starter.forestry.support;

/**
 * 业务异常：携带 HTTP 状态码与稳定错误码，由全局异常处理器转换为响应体。
 */
public class ForestryException extends RuntimeException {

    private final int httpStatus;
    private final String code;

    public ForestryException(int httpStatus, String code, String message) {
        super(message);
        this.httpStatus = httpStatus;
        this.code = code;
    }

    public int httpStatus() {
        return httpStatus;
    }

    public String code() {
        return code;
    }

    /**
     * 幂等冲突：同 requestId 不同业务参数，返回 409 且不产生任何副作用。
     */
    public static ForestryException idempotencyConflict(String requestId) {
        return new ForestryException(409, "IDEMPOTENCY_CONFLICT",
                "requestId " + requestId + " 已存在但业务参数不一致");
    }

    /**
     * 资源不存在。
     */
    public static ForestryException notFound(String what) {
        return new ForestryException(404, "NOT_FOUND", what + " 不存在");
    }

    /**
     * 状态冲突（如证件已作废、限额不足、小班已有有效证等）。
     */
    public static ForestryException conflict(String code, String message) {
        return new ForestryException(409, code, message);
    }
}

package com.example.starter.forestry.support;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * 幂等指纹工具：以 requestId 与全部业务字段拼接的规范串计算 SHA-256。
 */
public final class Fingerprints {

    private Fingerprints() {
    }

    /**
     * 计算幂等指纹。字段按声明顺序以竖线连接，null 以空串占位。
     *
     * @param fields 第一个元素必须为 requestId，其后为全部业务字段
     * @return 64 位十六进制摘要
     */
    public static String of(Object... fields) {
        StringBuilder sb = new StringBuilder();
        for (Object field : fields) {
            sb.append(field == null ? "" : field.toString()).append('|');
        }
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(sb.toString().getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }
}

